from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}  # id -> dict with patient, doctor, start, end, cancelled_recently
        self._next_id = 1

    def _is_freed(self, appt: dict) -> bool:
        """Return True if this appointment no longer blocks its time slot."""
        if not appt.get("cancelled"):
            return False
        # If cancelled, freed only if cancellation was >= 24h before start.
        return appt.get("freed", False)

    def _blocks_slot(self, appt: dict) -> bool:
        return not self._is_freed(appt)

    def _overlaps(self, s1: datetime, e1: datetime, s2: datetime, e2: datetime) -> bool:
        return s1 < e2 and s2 < e1

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Cannot book an appointment starting before now")
        if end <= start:
            raise ValueError("Appointment end must be after start")

        # Check doctor overlap
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if not self._blocks_slot(appt):
                continue
            if self._overlaps(start, end, appt["start"], appt["end"]):
                raise ValueError("Doctor has an overlapping appointment")

        # Check patient: at most one upcoming (non-cancelled-freed) appointment
        for appt in self._appointments.values():
            if appt["patient"] != patient:
                continue
            if appt.get("cancelled"):
                # Cancelled appointments: does it still count as "upcoming"?
                # A non-freed cancelled slot stays blocked but shouldn't count as
                # an active upcoming appointment for the patient. Count only
                # active (non-cancelled) appointments whose start > now.
                continue
            if appt["start"] > now:
                raise ValueError("Patient already has an upcoming appointment")

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "cancelled": False,
            "freed": False,
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise ValueError("Unknown appointment id")
        appt = self._appointments[appointment_id]
        if appt.get("cancelled"):
            return
        appt["cancelled"] = True
        # Free the slot only if cancellation is at least 24h before start.
        if appt["start"] - now >= timedelta(hours=24):
            appt["freed"] = True
        else:
            appt["freed"] = False

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if not self._blocks_slot(appt):
                continue
            if self._overlaps(start, end, appt["start"], appt["end"]):
                return False
        return True
